import{_ as l,r as t,o as i,c as r,e,a as n,s as p,d as a}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"控制器 - October CMS - 3.x","titleTemplate":false,"description":"创建实现各种功能的页面，如表单和列表。","frontmatter":{"subtitle":"创建实现各种功能的页面，如表单和列表。"},"headers":[{"level":3,"title":"类定义","slug":"类定义","link":"#类定义","children":[]},{"level":3,"title":"控制器属性","slug":"控制器属性","link":"#控制器属性","children":[]},{"level":2,"title":"初始化逻辑","slug":"初始化逻辑","link":"#初始化逻辑","children":[]},{"level":2,"title":"操作、视图和路由","slug":"操作、视图和路由","link":"#操作、视图和路由","children":[]},{"level":2,"title":"向视图传递数据","slug":"向视图传递数据","link":"#向视图传递数据","children":[]},{"level":2,"title":"设置导航上下文","slug":"设置导航上下文","link":"#设置导航上下文","children":[]},{"level":2,"title":"覆盖响应","slug":"覆盖响应","link":"#覆盖响应","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/extend/system/controllers.md","filePath":"3.x/zh-cn/extend/system/controllers.md"}'),u={name:"3.x/zh-cn/extend/system/controllers.md"};function d(k,s,g,h,m,v){const o=t("pre-heading"),c=t("post-heading");return i(),r("div",null,[e(o),s[0]||(s[0]=n("h1",null,"控制器",-1)),e(c),s[1]||(s[1]=p(`<p>October CMS 后端实现了模型-视图-控制器（MVC）模式。本文介绍如何开发后端控制器以及如何配置控制器行为。</p><p>每个控制器都由一个 PHP 脚本表示，该脚本位于插件目录的 <strong>/controllers</strong> 子目录中。控制器视图是 <code>.php</code> 文件，位于控制器视图目录中。控制器视图目录名称与以小写形式书写的控制器类名匹配。视图目录还可以包含控制器配置文件。以下是控制器目录结构的示例：</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>controllers</code>
|           |   ├── users  <em>← 视图目录</em>
|           |   |   ├── config_form.yaml  <em>← 配置文件</em>
|           |   |   ├── _partial.php  <em>← 局部视图文件</em>
|           |   |   └── index.php  <em>← 视图文件</em>
|           |   └── Users.php  <em>← 控制器类</em>
|           └── Plugin.php</p>
</code></pre>`,3)),s[2]||(s[2]=n("div",{class:"custom-block tip"},[n("p",null,[a("有关使用后端控制器的实际示例，请查看 "),n("a",{href:"https://octobercms.com/support/article/ob-19",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Beyond Behaviors 教程系列"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a("。")])],-1)),s[3]||(s[3]=p(`<h3 id="类定义"><a href="#类定义" class="header-anchor">#</a> 类定义</h3><p><code>create:controller</code> 命令会生成控制器、配置和视图文件。第一个参数指定作者和插件名称。第二个参数指定控制器类名。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:controller Acme.Blog Posts
</code></pre></div><p>控制器类必须继承 <code>Backend\\Classes\\Controller</code> 类。与任何其他插件类一样，控制器应属于<a href="./../system/plugins.html">插件命名空间</a>。在插件中使用的控制器的最基本表示如下所示。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span>    <span class="token comment">// ← Action method</span>
    <span class="token punctuation">{</span>

    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>通常每个控制器实现与单一类型数据交互的功能——例如博客文章或分类。下面描述的所有后端行为都遵循这一约定。</p><h3 id="控制器属性"><a href="#控制器属性" class="header-anchor">#</a> 控制器属性</h3><p>后端控制器基类定义了许多属性，允许配置页面外观和管理页面安全：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>$fatalError</strong></td><td>允许存储在操作方法中生成的致命异常，以便在视图中显示。</td></tr><tr><td><strong>$user</strong></td><td>包含对后端用户对象的引用。</td></tr><tr><td><strong>$suppressView</strong></td><td>允许阻止视图显示。可以在操作方法或控制器构造函数中更新。</td></tr><tr><td><strong>$params</strong></td><td>路由参数的数组。</td></tr><tr><td><strong>$action</strong></td><td>当前请求中正在执行的操作方法的名称。</td></tr><tr><td><strong>$publicActions</strong></td><td>定义无需后端用户认证即可访问的操作数组。可以在类定义中覆盖。</td></tr><tr><td><strong>$requiredPermissions</strong></td><td>查看此页面所需的权限。可以在类定义或控制器构造函数中设置。详情请参阅<a href="./../backend/users.html">用户和权限</a>。</td></tr><tr><td><strong>$pageTitle</strong></td><td>设置页面标题。可以在操作方法中设置。</td></tr><tr><td><strong>$bodyClass</strong></td><td>用于自定义布局的 body 类属性。可以在控制器构造函数或操作方法中设置。</td></tr><tr><td><strong>$guarded</strong></td><td>不能作为操作调用的控制器特定方法。可以在控制器构造函数中扩展。</td></tr><tr><td><strong>$layout</strong></td><td>为<a href="./../system/views.html">控制器视图</a>指定自定义布局。</td></tr></tbody></table></div><h2 id="初始化逻辑"><a href="#初始化逻辑" class="header-anchor">#</a> 初始化逻辑</h2><p>控制器可以在原生 <code>__construct</code> 方法中执行初始化逻辑。</p><div class="custom-block warning"><p>构造函数内的逻辑不受保护，不应处理任何敏感逻辑。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div></div><p><code>beforeDisplay</code> 方法在权限检查之后调用，大多数逻辑应放在这里。这包括初始化小部件和其他共享组件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeDisplay</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Initialize widgets, handle file uploads, etc.</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="操作、视图和路由"><a href="#操作、视图和路由" class="header-anchor">#</a> 操作、视图和路由</h2><p>公共控制器方法，称为<strong>操作</strong>，与代表该操作对应页面的<strong>视图文件</strong>相关联。后端视图文件使用 PHP 语法。以下是 <strong>index.php</strong> 视图文件内容的示例，对应 <code>index</code> 操作方法。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello World<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>此页面的 URL 由作者名称、插件名称、控制器名称和操作名称组成。</p><div class="language-text extra-class"><pre class="language-text"><code>admin/[author name]/[plugin name]/[controller name]/[action name]
</code></pre></div><p>例如，本文开头使用的类定义可以通过以下 URL 访问。</p><div class="language-text extra-class"><pre class="language-text"><code>https://example.tld/admin/acme/blog/users/index
</code></pre></div><p>如果<a href="./plugins.html">插件已注册</a>并在 <code>pluginDetails</code> 方法中设置了 <strong>hint</strong>，则可以使用更短的 URL 结构，这对于在 URL 中隐藏作者名称很有用。</p><div class="language-text extra-class"><pre class="language-text"><code>admin/[plugin hint]/[controller name]/[action name]
</code></pre></div><h2 id="向视图传递数据"><a href="#向视图传递数据" class="header-anchor">#</a> 向视图传递数据</h2><p>使用控制器的 <code>$vars</code> 属性将任何数据直接传递给你的视图：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;myVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>通过 <code>$vars</code> 属性传递的变量现在可以在你的视图中直接访问：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The variable value is <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$myVariable</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="设置导航上下文"><a href="#设置导航上下文" class="header-anchor">#</a> 设置导航上下文</h2><p>插件可以在<a href="./../backend/navigation.html">插件注册文件</a>中注册后端导航菜单和子菜单。导航上下文决定了当前后端页面的活动菜单和子菜单。你可以使用 <code>BackendMenu</code> 类设置导航上下文：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第一个参数指定作者和插件名称。第二个参数设置菜单代码。可选的第三个参数指定子菜单代码。通常你在控制器构造函数中调用 <code>BackendMenu::setContext</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span> <span class="token punctuation">{</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>你可以使用控制器类的 <code>$pageTitle</code> 属性设置后端页面的标题（注意表单和列表行为可以为你完成此操作）：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">pageTitle</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Blog Categories&#39;</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="覆盖响应"><a href="#覆盖响应" class="header-anchor">#</a> 覆盖响应</h2><p>你可以在后端控制器中覆盖响应，作为修改 HTTP 请求响应的机制。例如，你可能希望为控制器中的某些操作指定 HTTP 头，或者在用户不满足某些条件时重定向用户。</p><p>覆盖响应在扩展其他控制器时特别有用。但是你也可能发现在本地调用这些方法很有用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>SomeController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">setResponseHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test-Header&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果你想检查路由的操作或参数，可以在控制器的 <code>getAction</code> 和 <code>getParams</code> 方法中找到它们。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context">Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>SomeController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">getAction</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;index&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Only do it for the index action</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">getParams</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token constant">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Only if first parameter exists</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要向响应添加头信息，可以调用 <code>setResponseHeader</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponseHeader</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test-Header&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要更改响应的状态码，使用 <code>setStatusCode</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setStatusCode</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要覆盖整个响应，调用 <code>setResponse</code> 方法，这将强制返回该响应，无论页面生命周期中发生了什么。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponse</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Page Not Found&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你也可以向此方法传递一个 <code>Response</code> 对象。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setResponse</span><span class="token punctuation">(</span><span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>查看<a href="./../services/response-view.html">视图与响应文章</a>以获取有关构建响应的更多信息。</p><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../services/response-view.html">视图和响应</a></li></ul></div>`,52))])}const b=l(u,[["render",d]]);export{x as __pageData,b as default};
